interactions.sample_code:
// Called once per edge, in the fixed order, for each of 4 passes.
// dist.s starts at 0; every other vertex starts at Infinity.
function relax(u, v, w) {
  if (dist(u) + w < dist(v)) {
    setDist(v, dist(u) + w);
    setPred(v, u);
    note(u + ' improves ' + v + ' to ' + (dist(u) + w));
  }
}

